/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field SalesUnit.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(SalesLine, SalesUnit), tableStr(UnitOfMeasure), fieldStr(UnitOfMeasure, Symbol))]
class METGUPPricingAttributeSalesLineSalesUnit  extends GUPPricingAttributeSalesLine implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>anytype</c> object</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).SalesUnit;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute in string</returns>
public str getName()
{
    return fieldPName(SalesLine, SalesUnit);
}

/// <summary>
/// Get attribte data type
/// </summary>
/// <returns><c>AttributeDataType</c> object</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

    /// <summary>
    /// specify the list of values applicable
    /// </summary>
    /// <returns><c>Set</c> object</returns>
    public Set getAllowedValuesWithDescription()
    {
        var ret = new Set(Types::AnyType);
        
        SalesLine       salesLine;
        UnitOfMeasure   unitOfMeasure;

        while select SalesUnit from salesLine
            join unitOfMeasure
            group by Symbol, UnitOfMeasureClass
            where salesLine.SalesUnit == unitOfMeasure.Symbol
        {
            GUPPricingAttributeAllowedValuesObject valueObject =
                new GUPPricingAttributeAllowedValuesObject(unitOfMeasure.Symbol, enum2Str(unitOfMeasure.UnitOfMeasureClass));
            ret.add(valueObject);
        }
        return ret;
    }

/// <summary>
/// return sales unit field.
/// </summary>
/// <returns><c>FieldId</c> value</returns>
public FieldId getField()
{
    return fieldNum(SalesLine, SalesUnit);
}
